/* Screen renderers consume the same normalized local architecture model. */
(() => {
  'use strict';
  const C = window.Cockpit;
  const M = C.model;
  const h = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  const byId = (items, id) => items.find(item => item.id === id);
  const nameOf = (items, id) => byId(items, id)?.name || 'Unknown';
  const sourceName = (data, id) => byId(data.sources, id)?.title || 'No source recorded';
  const options = (choices, current) => choices.map(value => `<option value="${h(value)}"${value === current ? ' selected' : ''}>${h(value)}</option>`).join('');
  const badge = value => `<span class="badge ${['Confirmed', 'Approved', 'Resolved', 'Architect Confirmed', 'Pass', 'Ready', 'Accepted', 'PASSED'].includes(value) ? 'good' : ['Open', 'Unresolved', 'Unknown', 'Architecture Decision Required', 'Fail', 'FAILED', 'Not Ready'].includes(value) ? 'attention' : 'neutral'}">${h(value)}</span>`;
  const heading = (eyebrow, title, description, extra = '') => `<div class="page-heading"><div><p class="eyebrow">${h(eyebrow)}</p><h1>${h(title)}</h1><p>${h(description)}</p></div>${extra}</div>`;
  const stateLabel = state => `${state} State`;
  const openDecisions = data => data.decisions.filter(item => item.status === 'Open' || item.status === 'Proposed');
  const stateDependencies = (data, state) => data.dependencies.filter(item => item.state === 'All' || item.state === state);

  function overview(data, ui) {
    const state = ui.state;
    const visible = M.visibleComponents(data, state);
    const rows = M.readinessFor(data, state);
    const totals = M.readinessCounts(rows);
    const unresolved = stateDependencies(data, state).filter(item => item.status === 'Unresolved');
    const decisions = openDecisions(data);
    const mappedDomains = data.domains.filter(domain => visible.some(component => component.domainId === domain.id)).length;
    return heading('Architecture visibility', 'Architecture Overview', 'See what is designed, what is evidenced and what remains unresolved.', `<span class="view-pill">${h(stateLabel(state))}</span>`) +
      `<div class="metric-grid">
        <article class="metric"><span>Domains mapped</span><strong>${mappedDomains}<small> / ${data.domains.length}</small></strong><p>Domains with components in this state</p></article>
        <article class="metric"><span>LLD statuses confirmed</span><strong>${totals.confirmed}<small> / ${totals.total}</small></strong><p>${totals.unknown} unknown categories</p></article>
        <article class="metric"><span>Open decisions</span><strong>${decisions.length}</strong><p>Open or proposed architecture decisions</p></article>
        <article class="metric"><span>Unresolved dependencies</span><strong>${unresolved.length}</strong><p>Component relationships needing clarity</p></article>
      </div>` +
      `<section class="panel"><div class="section-head"><div><p class="eyebrow">Architecture readiness</p><h2>Domains</h2></div><span class="muted">Select a domain to inspect the topology</span></div><div class="domain-grid">${data.domains.map(domain => {
        const components = visible.filter(item => item.domainId === domain.id);
        const siteIds = new Set(components.map(item => item.siteId).filter(Boolean));
        const counts = M.readinessCounts(rows.filter(item => siteIds.has(item.siteId)));
        return `<button type="button" class="domain-card" data-action="open-domain" data-id="${h(domain.id)}"><span class="domain-icon">◈</span><strong>${h(domain.name)}</strong><span>${components.length} ${components.length === 1 ? 'component' : 'components'} in view</span><small>${counts.total ? `${counts.confirmed}/${counts.total} LLD statuses confirmed` : 'No site LLD linked yet'}</small></button>`;
      }).join('')}</div></section>` +
      `<div class="two-column"><section class="panel"><div class="section-head"><div><p class="eyebrow">Design intent</p><h2>Open architecture decisions</h2></div><span class="count-pill">${decisions.length}</span></div>${decisions.length ? decisions.map(item => `<button type="button" class="item-row" data-action="open-decision" data-id="${h(item.id)}"><span><small>${h(item.code)} · ${h(nameOf(data.domains, item.domainId))}</small><strong>${h(item.title)}</strong></span>${badge(item.status)}</button>`).join('') : '<p class="muted">No open architecture decisions.</p>'}</section>
      <section class="panel"><div class="section-head"><div><p class="eyebrow">Dependencies</p><h2>Unresolved relationships</h2></div><span class="count-pill">${unresolved.length}</span></div>${unresolved.length ? unresolved.slice(0, 5).map(item => `<button type="button" class="item-row" data-action="open-dependency" data-id="${h(item.downstreamId)}"><span><small>${h(nameOf(data.components, item.upstreamId))} → ${h(nameOf(data.components, item.downstreamId))}</small><strong>${h(item.description)}</strong></span>${badge(item.status)}</button>`).join('') : '<p class="muted">No unresolved component dependencies.</p>'}</section></div>` +
      `<section class="panel"><div class="section-head"><div><p class="eyebrow">LLD coverage</p><h2>Site readiness</h2></div><span class="muted">${h(stateLabel(state))}</span></div><div class="site-grid">${data.sites.map(site => {
        const counts = M.readinessCounts(M.readinessFor(data, state, site.id));
        return `<button type="button" class="site-card" data-action="open-readiness" data-id="${h(site.id)}"><strong>${h(site.name)}</strong><small>${h(site.siteType)}</small><span>${counts.confirmed} confirmed · ${counts.unknown} unknown · ${counts.total} categories</span></button>`;
      }).join('')}</div></section>`;
  }

  function topology(data, ui) {
    const visible = M.visibleComponents(data, ui.state, ui.domainFilter);
    const selected = visible.find(item => item.id === ui.selectedComponentId) || visible[0];
    const componentState = data.componentStates.find(item => item.componentId === selected?.id && item.state === ui.state);
    const site = byId(data.sites, selected?.siteId);
    const subnets = data.subnets.filter(item => item.siteId === site?.id);
    const decisions = data.decisions.filter(item => item.affectedComponentIds.includes(selected?.id));
    const dependencies = data.dependencies.filter(item => item.upstreamId === selected?.id || item.downstreamId === selected?.id);
    return heading('Logical architecture', 'Topology', 'Pan, zoom and select a component to inspect its design context.', `<span class="view-pill">${h(stateLabel(ui.state))}</span>`) +
      `<div class="toolbar"><label>Domain <select id="domain-filter"><option value="">All domains</option>${data.domains.map(domain => `<option value="${h(domain.id)}"${ui.domainFilter === domain.id ? ' selected' : ''}>${h(domain.name)}</option>`).join('')}</select></label><span class="muted">${visible.length} components · ${M.visibleLinks(data, ui.state, visible).length} connections</span><div class="zoom-controls"><button type="button" data-action="zoom-out" aria-label="Zoom out">−</button><button type="button" data-action="zoom-in" aria-label="Zoom in">+</button><button type="button" data-action="zoom-fit">Fit</button></div></div>` +
      `<div class="topology-layout"><section class="panel graph-panel"><svg id="topology-svg" class="topology-svg" viewBox="-15 -40 1210 640" role="img" aria-label="Interactive logical network topology"></svg>${visible.length ? '' : `<p class="graph-empty">No components are modelled for this domain in ${h(stateLabel(ui.state))}.</p>`}<p class="graph-hint">Drag to pan · Scroll or use the controls to zoom · Select a node</p></section>
      <aside class="panel detail-panel">${selected ? `<p class="eyebrow">Selected component</p><h2>${h(selected.name)}</h2><p>${h(selected.description)}</p><dl><dt>Domain</dt><dd>${h(nameOf(data.domains, selected.domainId))}</dd><dt>Type</dt><dd>${h(selected.type)}</dd><dt>Site</dt><dd>${h(site?.name || 'Programme-wide')}</dd><dt>Perspective</dt><dd>${h(componentState?.perspective || 'Unknown')}</dd><dt>Classification</dt><dd>${h(componentState?.classification || 'Unknown')}</dd><dt>Source</dt><dd>${h(sourceName(data, componentState?.sourceId))}</dd></dl>${subnets.length ? `<div class="detail-block"><h3>Example addressing</h3>${subnets.map(item => `<p><code>${h(item.cidr)}</code> <small>${h(item.purpose)}</small></p>`).join('')}</div>` : ''}<div class="detail-block"><h3>Linked architecture</h3><p>${dependencies.length} dependencies · ${decisions.length} decisions</p>${decisions.map(item => `<p>${badge(item.status)} ${h(item.code)}: ${h(item.title)}</p>`).join('')}</div><button type="button" class="button button-primary" data-action="open-dependency" data-id="${h(selected.id)}">View dependencies</button>` : '<div class="empty-state"><span>◇</span><h2>Select a component</h2><p>Inspect its evidence classification and relationships.</p></div>'}</aside></div>`;
  }

  function readiness(data, ui) {
    const site = byId(data.sites, ui.selectedSiteId) || data.sites[0];
    const rows = M.readinessFor(data, ui.state, site?.id);
    const counts = M.readinessCounts(rows);
    const byCategory = new Map(rows.map(item => [item.category, item]));
    return heading('Design completeness', 'LLD Readiness', 'Review the architecture inputs needed for a usable low-level design.', `<span class="view-pill">${h(stateLabel(ui.state))}</span>`) +
      `<section class="panel readiness-summary"><label>Site <select id="readiness-site">${data.sites.map(item => `<option value="${h(item.id)}"${item.id === site?.id ? ' selected' : ''}>${h(item.name)}</option>`).join('')}</select></label><div><strong>${counts.confirmed} / ${counts.total}</strong><small>statuses confirmed</small></div><div><strong>${counts.unknown}</strong><small>unknown</small></div><p class="muted">Status and evidence classification are separate. Changing a status never confirms evidence automatically.</p></section>` +
      `<section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">${h(site?.siteType || 'Site')}</p><h2>${h(site?.name || 'No site selected')}</h2></div>${badge(stateLabel(ui.state))}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Category</th><th>LLD status</th><th>Evidence classification</th><th>Architect note / source</th><th></th></tr></thead><tbody>${M.readinessCategories.map(category => {
        const item = byCategory.get(category);
        return item ? `<tr data-readiness-row="${h(item.id)}"><th scope="row">${h(category)}</th><td><select data-field="status" aria-label="${h(category)} status">${options(M.readinessStatuses, item.status)}</select></td><td><select data-field="classification" aria-label="${h(category)} classification">${options(M.classifications, item.classification)}</select></td><td><input data-field="note" aria-label="${h(category)} note" maxlength="1000" value="${h(item.note)}"></td><td><button type="button" class="button button-small" data-action="save-readiness" data-id="${h(item.id)}">Save</button></td></tr>` : `<tr><th scope="row">${h(category)}</th><td colspan="4" class="muted">Not yet modelled</td></tr>`;
      }).join('')}</tbody></table></div></section>`;
  }

  function nextDecisionCode(data) {
    const greatest = Math.max(0, ...data.decisions.map(item => Number(/^ADR-(\d+)$/.exec(item.code)?.[1] || 0)));
    return `ADR-${String(greatest + 1).padStart(3, '0')}`;
  }
  function decisions(data, ui) {
    const selected = byId(data.decisions, ui.selectedDecisionId);
    const draft = selected || { id: '', code: nextDecisionCode(data), title: '', domainId: data.domains[0]?.id || '', status: 'Open', decision: '', rationale: '', supersededDecisionId: null, affectedComponentIds: [], sourceId: null, sourceLabel: '', date: '', classification: 'Unknown' };
    return heading('Design governance', 'Architecture Decisions', 'Record decisions, rationale, affected components and provenance.', '<button type="button" class="button button-primary" data-action="new-decision">New decision</button>') +
      `<div class="decision-layout"><aside class="panel decision-list"><label>Find a decision <input id="decision-search" type="search" placeholder="ID, title or domain" value="${h(ui.decisionSearch || '')}"></label><div id="decision-items">${data.decisions.map(item => `<button type="button" class="decision-item${item.id === selected?.id ? ' active' : ''}" data-action="select-decision" data-id="${h(item.id)}" data-search="${h(`${item.code} ${item.title} ${nameOf(data.domains, item.domainId)}`.toLowerCase())}"><small>${h(item.code)} · ${h(nameOf(data.domains, item.domainId))}</small><strong>${h(item.title)}</strong>${badge(item.status)}</button>`).join('')}</div></aside>
      <section class="panel decision-form-panel"><div class="section-head"><div><p class="eyebrow">${selected ? 'Decision record' : 'New record'}</p><h2>${h(selected?.code || 'New architecture decision')}</h2></div>${badge(draft.classification)}</div><form id="decision-form"><input name="id" type="hidden" value="${h(draft.id)}"><div class="form-grid"><label>ID <input name="code" required maxlength="40" value="${h(draft.code)}"></label><label>Domain <select name="domainId" required>${data.domains.map(domain => `<option value="${h(domain.id)}"${domain.id === draft.domainId ? ' selected' : ''}>${h(domain.name)}</option>`).join('')}</select></label></div>
      <label>Title <input name="title" required maxlength="200" value="${h(draft.title)}" placeholder="What needs to be decided?"></label><div class="form-grid"><label>Status <select name="status">${options(M.decisionStatuses, draft.status)}</select></label><label>Date <input name="date" type="date" value="${h(draft.date)}"></label></div>
      <label>Decision <textarea name="decision" rows="3" maxlength="4000" placeholder="State the decision or leave blank while open.">${h(draft.decision)}</textarea></label><label>Rationale <textarea name="rationale" rows="3" maxlength="4000">${h(draft.rationale)}</textarea></label><div class="form-grid"><label>Evidence classification <select name="classification">${options(M.classifications, draft.classification)}</select></label><label>Superseded decision <select name="supersededDecisionId"><option value="">None</option>${data.decisions.filter(item => item.id !== draft.id).map(item => `<option value="${h(item.id)}"${item.id === draft.supersededDecisionId ? ' selected' : ''}>${h(item.code)} — ${h(item.title)}</option>`).join('')}</select></label></div>
      <label>Source label <input name="sourceLabel" maxlength="300" value="${h(draft.sourceLabel)}" placeholder="Document, workshop or architect validation"></label><label>Source record <select name="sourceId"><option value="">None</option>${data.sources.map(item => `<option value="${h(item.id)}"${item.id === draft.sourceId ? ' selected' : ''}>${h(item.title)}</option>`).join('')}</select></label>
      <fieldset><legend>Affected components</legend><div class="checkbox-grid">${data.components.map(item => `<label><input type="checkbox" name="affectedComponentIds" value="${h(item.id)}"${draft.affectedComponentIds.includes(item.id) ? ' checked' : ''}>${h(item.name)}</label>`).join('')}</div></fieldset><div class="form-footer"><small>Stable record UUID: ${h(draft.id || 'generated on save')}</small><button class="button button-primary" type="submit">Save decision</button></div></form></section></div>`;
  }

  function dependencies(data, ui) {
    const components = M.visibleComponents(data, ui.state);
    const selected = byId(components, ui.selectedComponentId) || components[0];
    const relevant = stateDependencies(data, ui.state);
    const upstream = relevant.filter(item => item.downstreamId === selected?.id);
    const downstream = relevant.filter(item => item.upstreamId === selected?.id);
    const decisions = data.decisions.filter(item => item.affectedComponentIds.includes(selected?.id) || relevant.some(dep => (dep.upstreamId === selected?.id || dep.downstreamId === selected?.id) && dep.decisionId === item.id));
    const unresolved = [...upstream, ...downstream].filter(item => item.status === 'Unresolved');
    const open = decisions.filter(item => item.status === 'Open' || item.status === 'Proposed');
    const dependencyCard = item => `<div class="dependency-card"><strong>${h(nameOf(data.components, item.upstreamId))} → ${h(nameOf(data.components, item.downstreamId))}</strong><p>${h(item.description)}</p>${badge(item.status)} <small>${h(item.classification)}</small><button type="button" class="text-link" data-action="toggle-dependency" data-id="${h(item.id)}">${item.status === 'Resolved' ? 'Reopen' : 'Mark resolved'}</button></div>`;
    return heading('Architecture relationships', 'Dependencies', 'Inspect what each component relies on and what relies on it.', `<span class="view-pill">${h(stateLabel(ui.state))}</span>`) +
      `<section class="panel component-picker"><label>Component <select id="dependency-component">${components.map(item => `<option value="${h(item.id)}"${item.id === selected?.id ? ' selected' : ''}>${h(item.name)}</option>`).join('')}</select></label><p class="muted">${h(selected?.description || 'No component selected.')}</p></section>` + (selected ?
      `<div class="metric-grid"><article class="metric"><span>Upstream</span><strong>${upstream.length}</strong><p>Components this one depends on</p></article><article class="metric"><span>Downstream</span><strong>${downstream.length}</strong><p>Components relying on this one</p></article><article class="metric"><span>Decisions</span><strong>${decisions.length}</strong><p>Linked architecture decisions</p></article><article class="metric"><span>Unresolved</span><strong>${unresolved.length + open.length}</strong><p>Relationships and decisions</p></article></div>
      <div class="two-column"><section class="panel"><div class="section-head"><div><p class="eyebrow">Inputs</p><h2>Upstream dependencies</h2></div><span class="count-pill">${upstream.length}</span></div>${upstream.length ? upstream.map(dependencyCard).join('') : '<p class="muted">No upstream dependencies recorded.</p>'}</section><section class="panel"><div class="section-head"><div><p class="eyebrow">Consumers</p><h2>Downstream dependencies</h2></div><span class="count-pill">${downstream.length}</span></div>${downstream.length ? downstream.map(dependencyCard).join('') : '<p class="muted">No downstream dependencies recorded.</p>'}</section></div>
      <div class="two-column"><section class="panel"><div class="section-head"><div><p class="eyebrow">Decision trail</p><h2>Architecture decisions</h2></div><span class="count-pill">${decisions.length}</span></div>${decisions.length ? decisions.map(item => `<button type="button" class="item-row" data-action="open-decision" data-id="${h(item.id)}"><span><small>${h(item.code)}</small><strong>${h(item.title)}</strong></span>${badge(item.status)}</button>`).join('') : '<p class="muted">No decisions linked.</p>'}</section><section class="panel"><div class="section-head"><div><p class="eyebrow">Items requiring clarity</p><h2>Unresolved items</h2></div><span class="count-pill">${unresolved.length + open.length}</span></div>${unresolved.map(item => `<div class="dependency-card"><strong>${h(nameOf(data.components, item.upstreamId))} → ${h(nameOf(data.components, item.downstreamId))}</strong><p>${h(item.description)}</p></div>`).join('')}${open.map(item => `<button type="button" class="item-row" data-action="open-decision" data-id="${h(item.id)}"><span><small>${h(item.code)} · ${h(item.status)}</small><strong>${h(item.title)}</strong></span></button>`).join('')}${!unresolved.length && !open.length ? '<p class="muted">No unresolved items for this component.</p>' : ''}</section></div>` : '');
  }

  function branches(data, ui) {
    const branch = byId(data.branches, ui.selectedBranchId) || data.branches[0];
    const site = byId(data.sites, branch?.siteId);
    const pattern = byId(data.branchPatterns, branch?.patternId);
    const devices = data.devices.filter(item => branch?.deviceIds.includes(item.id));
    const interfaces = data.interfaces.filter(item => devices.some(device => device.id === item.deviceId));
    const circuits = data.circuits.filter(item => item.siteId === branch?.siteId);
    const subnets = data.subnets.filter(item => item.siteId === branch?.siteId);
    const counts = M.readinessCounts(M.readinessFor(data, ui.state, site?.id));
    const evidence = data.branchEvidence.filter(item => item.branchId === branch?.id);
    const targets = M.branchEvidenceTargets(data, branch?.id);
    const assuranceRun = C.assurance.latestRun(data, branch?.id);
    const assuranceResults = data.assuranceResults.filter(item => item.runId === assuranceRun?.id);
    const assuranceStatus = C.assurance.evaluateAcceptance(data, assuranceRun?.id);
    const attributeSection = (category, items) => `<section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">${h(category)} architecture</p><h2>${h(category)}</h2></div><span class="muted">Unknown stays unknown until an architect records evidence.</span></div><div class="table-scroll"><table class="data-table branch-table"><thead><tr><th>Item</th><th>Current value</th><th>Evidence classification</th><th>Source / provenance</th><th>Note</th><th></th></tr></thead><tbody>${items.map(([key, label]) => {
      const item = data.branchAttributes.find(entry => entry.branchId === branch.id && entry.category === category && entry.key === key);
      return `<tr data-attribute-row data-category="${h(category)}" data-key="${h(key)}"><th scope="row">${h(label)}</th><td><input data-field="value" aria-label="${h(label)} value" maxlength="500" value="${h(item?.value || '')}" placeholder="Unknown"></td><td><select data-field="classification" aria-label="${h(label)} classification">${options(M.classifications, item?.classification || 'Unknown')}</select></td><td><input data-field="source" aria-label="${h(label)} source" maxlength="200" value="${h(item?.source || '')}" placeholder="Source label"></td><td><input data-field="note" aria-label="${h(label)} note" maxlength="1000" value="${h(item?.note || '')}"></td><td><button class="button button-small" type="button" data-action="save-attribute">Save</button></td></tr>`;
    }).join('')}</tbody></table></div></section>`;
    const deltas = M.branchDeltas(data, branch?.id);
    return heading('Branch intelligence', 'Branch Detail', 'Record branch evidence and compare current observations with an inherited target pattern.', '<button type="button" class="button button-primary" data-action="new-branch">Add branch</button>') +
      (ui.newBranch ? `<section class="panel"><div class="section-head"><div><p class="eyebrow">Progressive enrichment</p><h2>Start a branch</h2></div><button type="button" class="text-link" data-action="cancel-new-branch">Cancel</button></div><p class="muted">Only a site name and proposed pattern are required. All other architecture values start Unknown.</p><form id="create-branch-form" class="branch-summary-form"><div class="form-grid"><label>Site / branch name <input name="name" required maxlength="160"></label><label>Site code <input name="siteCode" maxlength="80" placeholder="Unknown"></label><label>Proposed pattern <select name="patternId">${data.branchPatterns.map(item => `<option value="${h(item.id)}">${h(item.code)} · ${h(item.name)}</option>`).join('')}</select></label></div><div class="form-footer"><small>Devices, circuits, evidence and LLD details can be added later.</small><button type="submit" class="button button-primary">Create branch</button></div></form></section>` : '') +
      `<div class="branch-layout"><aside class="panel branch-list"><p class="eyebrow">Branch estate</p>${data.branches.map(item => `<button type="button" class="branch-item${item.id === branch?.id ? ' active' : ''}" data-action="open-branch" data-id="${h(item.id)}"><strong>${h(item.name)}</strong><small>${h(item.siteCode || 'Site code unknown')}</small></button>`).join('')}<button class="text-link" type="button" data-screen="estate">View estate matrix</button><button class="text-link" type="button" data-screen="patterns">View pattern catalogue</button></aside><div class="branch-main">${branch ?
      `<section class="panel"><div class="section-head"><div><p class="eyebrow">Summary</p><h2>${h(branch.name)}</h2></div>${data.programme.isDemo ? badge('Synthetic demo') : ''}</div><div class="summary-facts"><div><small>LLD readiness · ${h(ui.state)}</small><strong>${counts.confirmed} confirmed · ${counts.unknown} unknown</strong></div><div><small>Evidence count</small><strong>${evidence.length}</strong></div><div><small>Last updated</small><strong>${h(branch.lastUpdated ? new Date(branch.lastUpdated).toLocaleString() : 'Unknown')}</strong></div><div><small>Assigned pattern</small><strong>${h(pattern?.code || 'Unknown')}</strong></div></div><form id="branch-summary-form" class="branch-summary-form"><input type="hidden" name="branchId" value="${h(branch.id)}"><div class="form-grid"><label>Site code <input name="siteCode" maxlength="80" value="${h(branch.siteCode)}"></label><label>Assigned Branch Pattern <select name="patternId">${data.branchPatterns.map(item => `<option value="${h(item.id)}"${item.id === branch.patternId ? ' selected' : ''}>${h(item.code)} · ${h(item.name)}</option>`).join('')}</select></label></div><label>Location description <input name="locationDescription" maxlength="500" value="${h(branch.locationDescription)}" placeholder="Unknown"></label><div class="form-grid"><label>Current-state confidence <select name="currentStateConfidence">${options(M.confidenceLevels, branch.currentStateConfidence)}</select></label><label>Deployment readiness <select name="deploymentReadiness">${options(M.deploymentStatuses, branch.deploymentReadiness)}</select></label><label>Validation status <select name="validationStatus">${options(M.validationStatuses, branch.validationStatus)}</select></label></div><div class="form-footer"><small>Manual statuses; no automatic acceptance decision.</small><button class="button button-primary" type="submit">Save summary</button></div></form></section>
      <section class="panel"><div class="section-head"><div><p class="eyebrow">Deployment assurance</p><h2>Separate domain results</h2></div>${badge(assuranceStatus.status)}</div><div class="assurance-branch-grid">${C.assurance.domains.map(domain => {
        const rows = assuranceResults.filter(item => data.assuranceRules.find(rule => rule.id === item.ruleId)?.domain === domain);
        const label = !assuranceRun || !rows.length ? 'Unknown' : rows.some(item => item.outcome === 'Fail') ? 'Fail' : rows.some(item => item.outcome === 'Unknown') ? 'Unknown' : rows.some(item => item.outcome === 'Warning') ? 'Warning' : rows.every(item => item.outcome === 'Not Applicable') ? 'Not Applicable' : 'Pass';
        return `<div><strong>${h(domain)}</strong>${badge(label)}</div>`;
      }).join('')}</div><button type="button" class="text-link" data-action="open-assurance" data-id="${h(branch.id)}">Inspect validation and gates</button></section>
      ${attributeSection('Physical', M.physicalItems)}${attributeSection('Logical', M.logicalItems)}
      <section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">Pattern inheritance</p><h2>Current vs Target</h2></div><span class="muted">${h(pattern?.code || 'No pattern')}</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Architecture area</th><th>Current State</th><th>Target Pattern</th><th>Delta</th></tr></thead><tbody>${deltas.map(row => `<tr><th scope="row">${h(row.label)}</th><td>${h(row.current)} <small>${h(row.classification)}</small></td><td>${h(row.target)}</td><td>${h(row.delta)}</td></tr>`).join('')}</tbody></table></div><p class="muted panel-note">Deltas compare recorded values with the assigned pattern. Photographs never produce technical facts automatically.</p></section>
      <section class="panel"><div class="section-head"><div><p class="eyebrow">Progressive inventory</p><h2>Devices, interfaces, circuits and addressing</h2></div></div><div class="inventory-grid"><div><h3>Devices · ${devices.length}</h3>${devices.map(item => `<p>${h(item.name)} <small>${h(item.role)} · ${h(item.vendor)}</small></p>`).join('') || '<p class="muted">Unknown</p>'}</div><div><h3>Interfaces · ${interfaces.length}</h3>${interfaces.map(item => `<p>${h(item.name)} <small>${h(nameOf(data.devices, item.deviceId))}</small></p>`).join('') || '<p class="muted">Unknown</p>'}</div><div><h3>Circuits · ${circuits.length}</h3>${circuits.map(item => `<p>${h(item.name)} <small>${h(item.provider)}</small></p>`).join('') || '<p class="muted">Unknown</p>'}</div><div><h3>Subnets · ${subnets.length}</h3>${subnets.map(item => `<p><code>${h(item.cidr)}</code> <small>${h(item.purpose)}</small></p>`).join('') || '<p class="muted">Unknown</p>'}</div></div><div class="inventory-forms"><details><summary>Add device</summary><form data-asset-form="Device"><input name="branchId" type="hidden" value="${h(branch.id)}"><label>Name <input name="name" required maxlength="160"></label><label>Role <input name="role" required maxlength="100" placeholder="WAN edge, switch or Wi-Fi AP"></label><label>Vendor <input name="vendor" maxlength="100"></label><button type="submit" class="button button-small">Add device</button></form></details><details><summary>Add interface</summary><form data-asset-form="Interface"><input name="branchId" type="hidden" value="${h(branch.id)}"><label>Device <select name="deviceId">${devices.map(item => `<option value="${h(item.id)}">${h(item.name)}</option>`).join('')}</select></label><label>Interface name <input name="name" required maxlength="160"></label><label>Description <input name="description" maxlength="500"></label><button type="submit" class="button button-small">Add interface</button></form></details><details><summary>Add circuit</summary><form data-asset-form="Circuit"><input name="branchId" type="hidden" value="${h(branch.id)}"><label>Name <input name="name" required maxlength="160"></label><label>Provider <input name="provider" maxlength="160"></label><label>Type <input name="circuitType" maxlength="100"></label><button type="submit" class="button button-small">Add circuit</button></form></details><details><summary>Add subnet</summary><form data-asset-form="Subnet"><input name="branchId" type="hidden" value="${h(branch.id)}"><label>CIDR <input name="cidr" required maxlength="80"></label><label>Purpose <input name="purpose" maxlength="500"></label><button type="submit" class="button button-small">Add subnet</button></form></details></div></section>
      <section class="panel"><div class="section-head"><div><p class="eyebrow">Provenance</p><h2>Evidence</h2></div><span class="count-pill">${evidence.length}</span></div><p class="muted">Add references or local photographs. Source files other than photographs remain outside the cockpit. No photograph confirms a technical fact automatically.</p><form id="branch-evidence-form" class="evidence-form"><input type="hidden" name="branchId" value="${h(branch.id)}"><div class="form-grid"><label>Type <select name="type" id="evidence-type">${options(M.evidenceTypes, 'Manual observation')}</select></label><label>Associated object <select name="target">${targets.map(item => `<option value="${h(`${item.kind}|${item.id}`)}">${h(item.label)}</option>`).join('')}</select></label></div><div class="form-grid"><label>Source <input name="source" required maxlength="200" placeholder="Document title, workshop or observer"></label><label>Date <input type="date" name="date" value="${h(new Date().toISOString().slice(0, 10))}"></label></div><div class="form-grid"><label>Classification <select name="classification">${options(M.classifications, 'Observed')}</select></label><label>Confidence <select name="confidence">${options(M.confidenceLevels, 'Unknown')}</select></label></div><label>Notes <textarea name="notes" rows="2" maxlength="1000"></textarea></label><label>Photograph (required when type is Photograph) <input id="evidence-photo-file" name="photo" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif"></label><div class="form-footer"><small>Photographs are saved only in this browser and in JSON backups.</small><button class="button button-primary" type="submit">Add evidence</button></div></form><div class="evidence-list">${evidence.length ? evidence.map(item => {
        const target = targets.find(entry => entry.kind === item.objectKind && entry.id === item.objectId);
        return `<div class="fact-row"><div><small>${h(item.id)} · ${h(item.type)} · ${h(item.date || 'Date unknown')}</small><strong>${h(target?.label || item.objectKind)}</strong><span>Source: ${h(item.source)} · Confidence: ${h(item.confidence)}</span><span>${h(item.notes)}</span></div><div>${badge(item.classification)}<button type="button" class="text-link" data-action="remove-evidence" data-id="${h(item.id)}">Remove</button></div></div>`;
      }).join('') : '<p class="muted">No evidence recorded yet.</p>'}</div><div id="photo-gallery" class="photo-grid" data-branch="${h(branch.id)}"></div></section>` : '<section class="panel"><p>No branches are modelled yet.</p></section>'}</div></div>`;
  }
  function estate(data, ui) {
    const columns = ['Physical', 'Circuits', 'IP Addressing', 'Routing', 'VLAN', 'VRF', 'SD-WAN', 'LAN', 'Wi-Fi', 'Evidence', 'LLD', 'Deployment'];
    return heading('Branch intelligence', 'Branch Estate Matrix', 'Explicit architecture states across the branch estate; Unknown remains visible.', `<span class="view-pill">${h(stateLabel(ui.state))}</span>`) +
      `<section class="panel table-panel"><div class="table-scroll"><table class="data-table estate-table"><thead><tr><th>Branch</th>${columns.map(column => `<th>${h(column)}</th>`).join('')}</tr></thead><tbody>${data.branches.map(branch => {
        const row = M.branchEstateRow(data, branch.id, ui.state);
        return `<tr><th><button type="button" class="text-link" data-action="open-branch" data-id="${h(branch.id)}">${h(branch.name)}</button><small>${h(branch.siteCode || 'Code unknown')}</small></th>${columns.map(column => `<td>${badge(row[column])}</td>`).join('')}</tr>`;
      }).join('')}</tbody></table></div></section><p class="muted">Matrix cells summarize recorded classifications or explicit LLD and deployment states. Mixed means multiple states are present, not a calculated percentage.</p>`;
  }
  function patterns(data, ui) {
    const selected = ui.selectedPatternId === 'new' ? null : byId(data.branchPatterns, ui.selectedPatternId) || data.branchPatterns[0];
    const draft = selected || { id: '', code: '', name: '', description: '', intendedUse: '', expectations: Object.fromEntries(M.expectationKeys.map(key => [key, null])) };
    const fields = [['wanEdgeQuantity', 'Expected WAN Edge quantity'], ['wanTransports', 'Expected WAN transports'], ['lanDevices', 'Expected LAN devices'], ['wifiApQuantity', 'Expected Wi-Fi AP quantity'], ['wifiSsids', 'Expected Wi-Fi SSIDs'], ['vlans', 'Expected VLANs'], ['vrfs', 'Expected VRFs'], ['sdwanVpns', 'Expected SD-WAN VPNs'], ['routing', 'Routing expectation'], ['resilience', 'Resilience expectation'], ['management', 'Management expectation'], ['lanHandoff', 'LAN handoff'], ['power', 'Power feeds'], ['optics', 'Optics']];
    return heading('Branch intelligence', 'Branch Pattern Catalogue', 'Reusable design intent inherited by branches, with unknown targets left blank.', '<button type="button" class="button button-primary" data-action="new-pattern">New pattern</button>') +
      `<div class="decision-layout"><aside class="panel decision-list"><p class="eyebrow">Patterns</p>${data.branchPatterns.map(item => `<button type="button" class="decision-item${item.id === selected?.id ? ' active' : ''}" data-action="select-pattern" data-id="${h(item.id)}"><small>${h(item.code)}</small><strong>${h(item.name)}</strong><span class="muted">${data.branches.filter(branch => branch.patternId === item.id).length} branches</span></button>`).join('')}</aside><section class="panel decision-form-panel"><div class="section-head"><div><p class="eyebrow">${selected ? 'Pattern record' : 'New pattern'}</p><h2>${h(selected?.name || 'Define a branch pattern')}</h2></div></div><form id="pattern-form"><input type="hidden" name="id" value="${h(draft.id)}"><div class="form-grid"><label>Pattern ID <input name="code" required maxlength="40" value="${h(draft.code)}" placeholder="BP-EXAMPLE-01"></label><label>Pattern name <input name="name" required maxlength="160" value="${h(draft.name)}"></label></div><label>Intended use <input name="intendedUse" maxlength="500" value="${h(draft.intendedUse)}"></label><label>Description <textarea name="description" rows="2" maxlength="4000">${h(draft.description)}</textarea></label><div class="form-grid">${fields.map(([key, label]) => `<label>${h(label)} <input name="${h(key)}" maxlength="300" value="${h(draft.expectations[key] || '')}" placeholder="Unknown"></label>`).join('')}</div><div class="form-footer"><small>Blank expectations remain unknown. Edits affect branches inheriting this pattern.</small><button type="submit" class="button button-primary">Save pattern</button></div></form></section></div>`;
  }
  function assuranceContext(data, ui) {
    const branch = byId(data.branches, ui.assuranceBranchId) || data.branches[0];
    const runs = data.assuranceRuns.filter(item => item.branchId === branch?.id);
    const run = runs.find(item => item.id === ui.selectedRunId) || C.assurance.latestRun(data, branch?.id);
    const baseline = byId(data.assuranceBaselines, run?.baselineId) || C.assurance.activeBaseline(data, branch?.id);
    const results = data.assuranceResults.filter(item => item.runId === run?.id);
    return { branch, runs, run, baseline, results, evaluation: C.assurance.evaluateAcceptance(data, run?.id) };
  }
  function assuranceHeading(data, ui, title, description) {
    const branch = assuranceContext(data, ui).branch;
    return heading('Deployment assurance', title, description) + `<div class="toolbar assurance-toolbar"><label>Branch <select id="assurance-branch">${data.branches.map(item => `<option value="${h(item.id)}"${item.id === branch?.id ? ' selected' : ''}>${h(item.siteCode || item.name)} · ${h(item.name)}</option>`).join('')}</select></label><span class="muted">Design Intent · Observed · Validated · As-Built remain separate</span></div>`;
  }
  function deployment(data, ui) {
    const { branch, run, baseline, results, evaluation } = assuranceContext(data, ui);
    const resultByRule = new Map(results.map(item => [item.ruleId, item]));
    return assuranceHeading(data, ui, 'Deployment', 'Compare the four architecture perspectives for the selected branch.') +
      `<div class="metric-grid"><article class="metric"><span>Deployment acceptance</span><strong class="metric-label">${h(evaluation.status)}</strong><p>Gate outcome: ${h(evaluation.gateOutcome)}</p></article><article class="metric"><span>Active design baseline</span><strong class="metric-label">${h(C.assurance.activeBaseline(data, branch?.id)?.name || 'None')}</strong><p>Design Intent snapshot</p></article><article class="metric"><span>Latest validation</span><strong class="metric-label">${h(run ? new Date(run.runAt).toLocaleDateString() : 'Not run')}</strong><p>${results.length} deterministic rule results</p></article><article class="metric"><span>As-Built observations</span><strong>${data.assuranceObservations.filter(item => item.branchId === branch?.id && item.perspective === 'As-Built').length}</strong><p>Stored separately from observed values</p></article></div>` +
      `<section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">Perspective comparison</p><h2>${h(branch?.name || 'No branch')}</h2></div>${badge(evaluation.gateOutcome)}</div><div class="table-scroll"><table class="data-table assurance-table"><thead><tr><th>Rule / domain</th><th>Design Intent</th><th>Observed State / source</th><th>Validated State</th><th>As-Built State / source</th></tr></thead><tbody>${data.assuranceRules.map(rule => {
        const result = resultByRule.get(rule.id);
        const observed = C.assurance.latestObservation(data, branch?.id, rule.id);
        const asBuilt = C.assurance.latestObservation(data, branch?.id, rule.id, 'As-Built');
        return `<tr><th scope="row">${h(rule.name)}<small>${h(rule.domain)} · ${h(rule.code)}</small></th><td>${h(result?.expected ?? baseline?.values[rule.id] ?? 'Unknown')}</td><td>${h(observed?.value || 'Unknown')}<small>${h(observed?.source || 'No source')}</small></td><td>${badge(result?.outcome || 'Unknown')}</td><td>${h(asBuilt?.value || 'Unknown')}<small>${h(asBuilt?.source || 'No source')}</small></td></tr>`;
      }).join('')}</tbody></table></div></section>`;
  }
  function deploymentReadiness(data, ui) {
    const { branch, results, evaluation } = assuranceContext(data, ui);
    return assuranceHeading(data, ui, 'Readiness', 'Inspect separate Physical, SD-WAN, LAN, Wi-Fi, Routing and Management results without project percentages.') +
      `<section class="panel"><div class="section-head"><h2>${h(branch?.name || 'No branch')}</h2>${badge(evaluation.status)}</div><p class="muted">Unknown and Not Applicable remain explicit. A run compares the active baseline with sourced observations.</p></section>` +
      `<div class="readiness-domain-grid">${C.assurance.domains.map(domain => {
        const rules = data.assuranceRules.filter(item => item.domain === domain);
        const domainResults = results.filter(item => rules.some(rule => rule.id === item.ruleId));
        const counts = Object.fromEntries(C.assurance.outcomes.map(outcome => [outcome, domainResults.filter(item => item.outcome === outcome).length]));
        return `<section class="panel"><div class="section-head"><h2>${h(domain)}</h2><span class="count-pill">${rules.length} rules</span></div><p class="assurance-counts">${C.assurance.outcomes.map(outcome => `${badge(outcome)} ${counts[outcome] || 0}`).join(' ')}</p>${rules.map(rule => {
          const result = domainResults.find(item => item.ruleId === rule.id);
          return `<div class="assurance-rule-row"><span>${h(rule.name)}<small>${h(rule.severity)}${rule.mandatory ? ' · mandatory' : ''}</small></span>${badge(result?.outcome || 'Unknown')}</div>`;
        }).join('')}</section>`;
      }).join('')}</div>`;
  }
  function validation(data, ui) {
    const { branch, runs, run, results, baseline } = assuranceContext(data, ui);
    const eligible = C.assurance.activeBaseline(data, branch?.id);
    return assuranceHeading(data, ui, 'Validation', 'Record a sourced observation or As-Built value, then run deterministic comparisons.') +
      `<section class="panel"><div class="section-head"><div><p class="eyebrow">Deterministic validation</p><h2>${h(branch?.name || 'No branch')}</h2></div><button type="button" class="button button-primary" data-action="run-validation"${eligible ? '' : ' disabled'}>Run validation</button></div><p class="muted">Active baseline: ${h(eligible?.name || 'None — activate a baseline first')} · Selected run: ${h(run ? new Date(run.runAt).toLocaleString() : 'None')}</p><div class="run-list">${runs.map(item => `<button type="button" class="button button-small${item.id === run?.id ? ' run-selected' : ''}" data-action="select-run" data-id="${h(item.id)}">${h(new Date(item.runAt).toLocaleString())}</button>`).join('')}</div></section>` +
      `<section class="panel"><div class="section-head"><div><p class="eyebrow">Source capture</p><h2>Record observed or As-Built value</h2></div></div><form id="assurance-observation-form" class="assurance-form"><input type="hidden" name="branchId" value="${h(branch?.id || '')}"><div class="form-grid"><label>Rule <select name="ruleId">${data.assuranceRules.map(item => `<option value="${h(item.id)}">${h(item.code)} · ${h(item.name)}</option>`).join('')}</select></label><label>Perspective <select name="perspective"><option>Observed</option><option>As-Built</option></select></label></div><div class="form-grid"><label>Value <input name="value" required maxlength="500" placeholder="Observed configuration or quantity"></label><label>Source <input name="source" required maxlength="200" placeholder="Manual Observation or synthetic source"></label></div><div class="form-footer"><small>Recording an observation never changes Design Intent or an earlier run.</small><button type="submit" class="button button-primary">Save value</button></div></form></section>` +
      `<section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">${h(baseline?.name || 'No baseline')}</p><h2>Rule results</h2></div><span class="count-pill">${results.length}</span></div><div class="table-scroll"><table class="data-table assurance-table"><thead><tr><th>Rule</th><th>Category</th><th>Severity</th><th>Target</th><th>Observed / source</th><th>Result</th></tr></thead><tbody>${data.assuranceRules.map(rule => {
        const result = results.find(item => item.ruleId === rule.id);
        return `<tr><th scope="row">${h(rule.name)}<small>${h(rule.code)}</small></th><td>${h(rule.category)}</td><td>${h(rule.severity)}${rule.mandatory ? ' · mandatory' : ''}</td><td>${h(result?.expected ?? baseline?.values[rule.id] ?? 'Unknown')}</td><td>${h(result?.observed || 'Unknown')}<small>${h(result?.observedSource || 'No source')}</small></td><td>${badge(result?.outcome || 'Unknown')}</td></tr>`;
      }).join('')}</tbody></table></div></section>`;
  }
  function exceptions(data, ui) {
    const { run, results } = assuranceContext(data, ui);
    const candidates = results.filter(item => ['Fail', 'Warning'].includes(item.outcome));
    const existing = data.assuranceExceptions.filter(item => item.runId === run?.id);
    const available = candidates.filter(item => !existing.some(exception => exception.resultId === item.id));
    return assuranceHeading(data, ui, 'Exceptions', 'Record and explicitly decide exceptions for a validation run.') +
      `<section class="panel"><p class="muted">An approved exception cannot override a failed Critical mandatory gate. Exceptions are tied to immutable run results.</p><form id="assurance-exception-form" class="assurance-form"><label>Failing or warning result <select name="resultId"${available.length ? '' : ' disabled'}>${available.map(item => `<option value="${h(item.id)}">${h(nameOf(data.assuranceRules, item.ruleId))} · ${h(item.outcome)} · ${h(item.severity)}</option>`).join('')}</select></label><label>Reason <textarea name="reason" required maxlength="1000" rows="2"></textarea></label><button type="submit" class="button button-primary"${available.length ? '' : ' disabled'}>Create exception</button></form></section>` +
      `<section class="panel"><div class="section-head"><h2>Exception records</h2><span class="count-pill">${existing.length}</span></div>${existing.length ? existing.map(item => {
        const result = results.find(entry => entry.id === item.resultId);
        return `<div class="dependency-card assurance-exception-card" data-exception-id="${h(item.id)}"><strong>${h(nameOf(data.assuranceRules, result?.ruleId))}</strong> ${badge(item.status)}<p>${h(item.reason)}</p><small>${h(result?.severity)} · ${h(result?.outcome)} · ${h(item.approvedBy || 'No approver')}</small>${item.status === 'Open' ? `<div class="exception-actions"><input data-approver maxlength="160" placeholder="Architect / approver"><button type="button" class="button button-small" data-action="decide-exception" data-id="${h(item.id)}" data-status="Approved">Approve</button><button type="button" class="button button-small" data-action="decide-exception" data-id="${h(item.id)}" data-status="Rejected">Reject</button></div>` : ''}</div>`;
      }).join('') : '<p class="muted">No exceptions for this run.</p>'}</section>`;
  }
  function acceptance(data, ui) {
    const { run, evaluation } = assuranceContext(data, ui);
    const canAccept = ['Ready', 'Ready with Exceptions'].includes(evaluation.status);
    return assuranceHeading(data, ui, 'Acceptance', 'Apply mandatory gates before an architect records acceptance.') +
      `<div class="metric-grid"><article class="metric"><span>Gate outcome</span><strong class="metric-label">${h(evaluation.gateOutcome)}</strong><p>Critical mandatory failure means FAILED</p></article><article class="metric"><span>Acceptance status</span><strong class="metric-label">${h(evaluation.status)}</strong><p>Explicit architect decision required</p></article><article class="metric"><span>Run</span><strong class="metric-label">${h(run ? new Date(run.runAt).toLocaleDateString() : 'None')}</strong><p>Results are immutable</p></article><article class="metric"><span>Exceptions</span><strong>${data.assuranceExceptions.filter(item => item.runId === run?.id).length}</strong><p>Approved exceptions never bypass Critical failures</p></article></div>` +
      `<section class="panel"><div class="section-head"><h2>Acceptance gates</h2>${badge(evaluation.gateOutcome)}</div>${evaluation.gateOutcome === 'FAILED' ? '<p class="gate-failed">Deployment Acceptance = FAILED</p>' : ''}${evaluation.gates.map(gate => `<div class="assurance-rule-row"><span>${h(gate.name)}<small>${h(gate.description)}</small></span>${badge(gate.outcome)}</div>`).join('') || '<p class="muted">No run selected.</p>'}</section>` +
      `<section class="panel"><h2>Architect decision</h2>${evaluation.record ? `<p>${badge(evaluation.record.status)} Signed by ${h(evaluation.record.architect)} on ${h(new Date(evaluation.record.signedAt).toLocaleString())}. ${h(evaluation.record.notes)}</p>` : `<p class="muted">${canAccept ? 'Gates permit an explicit decision.' : 'Acceptance is unavailable while gates fail or remain pending.'}</p><form id="assurance-acceptance-form" class="assurance-form"><input type="hidden" name="runId" value="${h(run?.id || '')}"><label>Architect name <input name="architect" required maxlength="160"></label><label>Decision note <textarea name="notes" maxlength="1000" rows="2"></textarea></label><button type="submit" class="button button-primary"${canAccept ? '' : ' disabled'}>${evaluation.status === 'Ready with Exceptions' ? 'Record conditional acceptance' : 'Record acceptance'}</button></form>`}</section>`;
  }
  function baselines(data, ui) {
    const { branch } = assuranceContext(data, ui);
    const items = data.assuranceBaselines.filter(item => item.branchId === branch?.id);
    const selected = byId(items, ui.selectedBaselineId) || C.assurance.activeBaseline(data, branch?.id) || items.at(-1);
    return assuranceHeading(data, ui, 'Baselines', 'Snapshot Design Intent and activate a reviewed target before validation.') +
      `<section class="panel"><div class="section-head"><div><h2>Design baselines</h2><p class="muted">A new draft inherits the assigned branch pattern. Blank targets are Unknown; enter N/A only when a rule truly does not apply.</p></div><button type="button" class="button button-primary" data-action="create-baseline">Create draft from pattern</button></div><div class="baseline-list">${items.map(item => `<button type="button" class="decision-item${item.id === selected?.id ? ' active' : ''}" data-action="select-baseline" data-id="${h(item.id)}"><small>${h(item.status)} · ${h(new Date(item.createdAt).toLocaleString())}</small><strong>${h(item.name)}</strong><span class="muted">${h(item.source)}</span></button>`).join('') || '<p class="muted">No baseline yet.</p>'}</div></section>` +
      (selected ? `<section class="panel table-panel"><div class="section-head"><div><p class="eyebrow">${h(selected.status)} · ${h(selected.source)}</p><h2>${h(selected.name)}</h2></div>${selected.status === 'Draft' ? `<button type="button" class="button button-primary" data-action="activate-baseline" data-id="${h(selected.id)}">Activate baseline</button>` : badge(selected.status)}</div><div class="table-scroll"><table class="data-table assurance-table"><thead><tr><th>Rule</th><th>Pattern target</th><th>Baseline target</th><th></th></tr></thead><tbody>${data.assuranceRules.map(rule => {
        const pattern = C.model.branchTarget(data, branch.id);
        return `<tr data-baseline-row data-rule-id="${h(rule.id)}" data-baseline-id="${h(selected.id)}"><th scope="row">${h(rule.name)}<small>${h(rule.code)}</small></th><td>${h(rule.patternKey ? pattern?.expectations[rule.patternKey] || 'Unknown' : 'Not in pattern')}</td><td>${selected.status === 'Draft' ? `<input data-target maxlength="500" value="${h(selected.values[rule.id] || '')}" placeholder="Unknown">` : h(selected.values[rule.id] || 'Unknown')}</td><td>${selected.status === 'Draft' ? '<button type="button" class="button button-small" data-action="save-baseline-target">Save</button>' : ''}</td></tr>`;
      }).join('')}</tbody></table></div></section>` : '');
  }
  C.views = Object.freeze({ h, badge, overview, topology, readiness, decisions, dependencies, branches, estate, patterns,
    deployment, deploymentReadiness, validation, exceptions, acceptance, baselines, sourceName });
})();
